INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o padrão-ouro atual para o diagnóstico de Tromboembolismo Pulmonar (TEP) no pós-operatório de pacientes com média ou alta probabilidade clínica?", "options": {"a": "Raio-x de tórax simples.", "b": "Angiotomografia de tórax (Protocolo para TEP).", "c": "D-dímero isolado.", "d": "Eletrocardiograma.", "e": "Cintilografia óssea."}, "answer": "b", "rationale": "A angiotomografia permite a visualização direta do trombo nas artérias pulmonares, sendo rápida e altamente acurada.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Exame de escolha diagnóstico.", "c": "Incorreta. D-dímero tem baixo valor preditivo positivo no pós-operatório (sempre alto por inflamação).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "TEP", "Diagnóstico"]}', 341, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes submetidos a cirurgia oncológica abdominal ou pélvica de grande porte, qual a recomendação atual de duração da profilaxia medicamentosa para TVP/TEP (Heparina de baixo peso molecular) após a alta hospitalar?", "options": {"a": "Apenas enquanto durar a internação.", "b": "Até completar 28 dias de pós-operatório (profilaxia estendida).", "c": "Apenas por 24 horas após a alta.", "d": "Uso eterno.", "e": "Não há indicação de manter após a alta."}, "answer": "b", "rationale": "O risco de eventos tromboembólicos em cirurgias de câncer persiste por semanas após a alta, justificando o uso estendido de anticoagulantes profiláticos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Protocolo de segurança em oncologia cirúrgica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Oncologia", "Pós-operatório", "TVP", "Profilaxia"]}', 342, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de febre entre o 7º e o 10º DPO, na ausência de focos infecciosos claros (pulmonar, urinário ou ferida), associada à eosinofilia ou erupção cutânea, deve levantar a suspeita de:", "options": {"a": "Abscesso hepático.", "b": "Febre Farmacológica (reação a medicamentos).", "c": "Sepse grave abdominal.", "d": "Apendicite remanescente.", "e": "Malária."}, "answer": "b", "rationale": "A febre medicamentosa é um diagnóstico de exclusão frequente em pacientes que utilizam muitos fármacos no pós-operatório (como antibióticos e anticonvulsivantes).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diferencial de febre hospitalar.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Clínica Médica", "Pós-operatório", "Febre", "Medicamentos"]}', 343, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a complicação biliar aguda que ocorre tipicamente em pacientes críticos em UTI (pós-operatórios graves, queimados ou politraumatizados), caracterizada por inflamação da vesícula SEM a presença de cálculos?", "options": {"a": "Colelitíase simples.", "b": "Colecistite Aguda Acalculosa.", "c": "Cálculo de colédoco.", "d": "Tumor de vesícula.", "e": "Fístula na uretra."}, "answer": "b", "rationale": "A estase biliar e a isquemia da mucosa da vesícula em pacientes graves propiciam a inflamação mesmo sem obstrução por pedra.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Patologia clássica do paciente crítico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Colecistite", "Acalculosa"]}', 344, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A meta de controle glicêmico recomendada para pacientes cirúrgicos internados em unidade de terapia intensiva, visando reduzir complicações infecciosas e mortalidade (segundo estudos de controle estrito vs moderado), é manter a glicemia entre:", "options": {"a": "70 a 90 mg/dL.", "b": "140 a 180 mg/dL.", "c": "250 a 300 mg/dL.", "d": "Normal absoluta (90-110).", "e": "Não importa o valor."}, "answer": "b", "rationale": "O controle muito estrito (< 110) aumenta o risco de hipoglicemia fatal. A faixa de 140-180 é considerada o alvo seguro e eficaz para pacientes críticos.", "option_rationales": {"a": "Incorreta. Risco alto de hipoglicemia.", "b": "Correta. Alvo glicêmico atual para pacientes internados.", "c": "Incorreta. Favorece infecções e retarda cicatrização.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Terapia Intensiva", "Pós-operatório", "Glicemia", "Diabetes"]}', 345, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de cirurgias torácicas ou abdominais altas, qual a principal utilidade da fisioterapia respiratória com ''espirometria de incentivo'' e tosse assistida?", "options": {"a": "Melhorar a força das pernas.", "b": "Prevenir e tratar atelectasias, aumentando o volume inspiratório e facilitando a limpeza de secreções brônquicas.", "c": "Aumentar a pressão arterial.", "d": "Reduzir o apetite.", "e": "Não tem utilidade comprovada."}, "answer": "b", "rationale": "A dor e o efeito anestésico reduzem a expansividade pulmonar. A fisioterapia foca em reabrir os alvéolos colapsados.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Pilar da recuperação respiratória perioperatória.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Fisioterapia", "Pós-operatório", "Atelectasia", "Recuperação"]}', 346, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A definição de ''Sepse'' (Sepsis-3) no pós-operatório envolve qual critério fundamental?", "options": {"a": "Apenas presença de pus na ferida.", "b": "Disfunção orgânica ameaçadora à vida causada por uma resposta desregulada do hospedeiro à infecção, avaliada pelo aumento de 2 ou mais pontos no escore SOFA.", "c": "Contagem de leucócitos acima de 20.000.", "d": "Auscência de febre.", "e": "Necessidade de nova cirurgia apenas."}, "answer": "b", "rationale": "A sepse não é apenas a infecção, mas sim a falência de órgãos decorrente da resposta inflamatória sistêmica à infecção.", "option_rationales": {"a": "Incorreta. Isso é infecção de sítio cirúrgico.", "b": "Correta. Definição diagnóstica internacional de sepse.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Infectologia", "Pós-operatório", "Sepse", "Diagnóstico"]}', 347, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia no 10º DPO apresenta queda súbita da Saturação de O2 para 85% e o Raio-x mostra infiltrado pulmonar bilateral difuso (''pulmão branco''), com relação PaO2/FiO2 < 200, sem evidência de falência cardíaca esquerda. Qual o diagnóstico?", "options": {"a": "Pneumonia isolada.", "b": "Síndrome do Desconforto Respiratório Agudo (SDRA).", "c": "Hemorragia digestiva.", "d": "Hérnia de hiato.", "e": "Asma leve."}, "answer": "b", "rationale": "A SDRA (ou ARDS) é uma reação inflamatória pulmonar grave que gera edema não-cardiogênico, muitas vezes secundária a foco séptico abdominal ou trauma.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Quadro clínico e radiológico compatível.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Terapia Intensiva", "Pós-operatório", "SDRA", "Pneumologia"]}', 348, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal vantagem do uso do ''curativo por pressão negativa'' (VAC - Vacuum Assisted Closure) em feridas operatórias infectadas ou deiscências complexas?", "options": {"a": "Acaba com a necessidade de antibióticos venosos.", "b": "Reduz o edema tecidual, remove secreções inflamatórias continuamente e estimula a formação de tecido de granulação através da microdeformação tecidual.", "c": "É mais barato que gaze simples.", "d": "Não precisa ser trocado nunca.", "e": "Melhora o sono do paciente."}, "answer": "b", "rationale": "O sistema VAC acelerou o fechamento de feridas complexas, criando um ambiente controlado e favorecendo a retração dos bordos da ferida.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Benefícios da terapia por pressão negativa.", "c": "Incorreta.", "d": "Incorreta. Deve ser trocado a cada 48-72h.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Ferida", "Presão Negativa"]}', 349, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''icterícia'' nas primeiras 24 horas de vida de um paciente recém-nascido submetido a cirurgia abdominal deve ser considerada sempre:", "options": {"a": "Normal e fisiológica.", "b": "Patológica, exigindo investigação imediata para causas como hemólise, infecção congênita ou obstrução anatômica biliar.", "c": "Efeito do leite materno.", "d": "Sintoma de fome.", "e": "Falta de sol apenas."}, "answer": "b", "rationale": "A icterícia fisiológica nunca começa nas primeiras 24h; o início precoce é um sinal de alerta de complicação grave.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Alerta clínico em neonatologia cirúrgica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pediatria", "Pós-operatório", "Icterícia", "Neonatologia"]}', 350, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a recomendação prioritária para um paciente que recebeu alta após uma cirurgia de grande porte e apresenta, em casa, vermelhidão, calor ou saída de pus pela cicatriz, associado a febre?", "options": {"a": "Passar álcool em gel na ferida e aguardar consulta de retorno em 15 dias.", "b": "Retornar imediatamente ao pronto-atendimento hospitalar ou entrar em contato com a equipe cirúrgica para avaliação de infecção de sítio cirúrgico.", "c": "Iniciar antibiótico por conta própria que tiver em casa.", "d": "Não fazer nada.", "e": "Colocar compressas de barro."}, "answer": "b", "rationale": "A detecção precoce de infecção permite o tratamento ambulatorial ou reospitalização se necessário, evitando a evolução para sepse ou deiscência profunda.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Orientação de alta e segurança do paciente.", "c": "Incorreta. Perigo de automedicação.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "ISC", "Segurança"]}', 351, 'draft')
